import json

def transform(grid):
    """Transform based on demo patterns"""
    h = len(grid)
    w = len(grid[0])

    # Find position of 3
    r3, c3 = None, None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                r3, c3 = r, c
                break
        if r3 is not None:
            break

    if r3 is None:
        return grid

    output = [[0]*w for _ in range(h)]

    # Span: 5 cols centered on c3
    span_left = c3 - 2
    span_right = c3 + 2

    # Fill 5s column at c3, rows r3-2 to r3 (the "5-stem" above and including 3's position)
    for c in range(span_left, span_right + 1):
        if 0 <= c < w:
            for r in range(r3 - 2, r3 + 1):
                if 0 <= r < h:
                    if r3 - 2 <= r <= r3:  # 5s area
                        output[r][c] = 5

    # The 3 stays at r3, c3 (overwrites the 5 at that position)
    output[r3][c3] = 3

    # Fill 2s columns at span_left and span_right (at the bottom of 5-stem)
    for r in range(r3 - 1, r3 + 3):
        for c in [span_left, span_right]:
            if 0 <= c < w and 0 <= r < h:
                output[r][c] = 2

    # Fill 8s at row r3+2, columns span_left to span_right
    if 0 <= r3 + 2 < h:
        for c in range(span_left, span_right + 1):
            if 0 <= c < w:
                output[r3+2][c] = 8

    return output

# Test with demo 2
