def transform(grid):
    """Transform based on demo patterns"""
    h = len(grid)
    w = len(grid[0])

    # Find position of 3
    r3, c3 = None, None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                r3, c3 = r, c
                break
        if r3 is not None:
            break

    if r3 is None:
        return grid

    output = [[0]*w for _ in range(h)]
    output[r3][c3] = 3

    # Span: 5 cols centered on c3
    span_left = c3 - 2
    span_right = c3 + 2

    # Row r3-2: 5s across full span
    for c in range(span_left, span_right + 1):
        if 0 <= c < w:
            output[r3-2][c] = 5

    # Rows r3-1 to r3: 
    #   - 5 only at center column c3 (but overwritten by 3 at r3)
    #   - 2s at border columns
    for r in range(r3-1, r3):  # r3-1 only, for 5-stem continuation
        c = c3
        if 0 <= c < w:
            output[r][c] = 5

    # 2s columns at span_left and span_right (starting from r3-1)
    for r in range(r3-1, r3+3):
        for c in [span_left, span_right]:
            if 0 <= c < w and 0 <= r < h:
                output[r][c] = 2

    # 2s on border row r3+2, full width (will be overwritten in span)
    if 0 <= r3 + 2 < h:
        for c in range(w):
            output[r3+2][c] = 2

    # 8s at row r3+2, full span (overwrite 2s)
    if 0 <= r3 + 2 < h:
        for c in range(span_left, span_right + 1):
            if 0 <= c < w:
                output[r3+2][c] = 8

    return output

